    if kx == "v" and ky == "e":
        return ax in ay
    if kx == "e" and ky == "v":
        return ay in ax
    return False


def central_degree(g: Graph, x: CVertex) -> int:
    return sum(1 for y in central_vertices(g) if central_adjacent(g, x, y))


def demo_degree_uniformity() -> None:
    """Every original vertex of C(G) has degree |V| - 1, independent of deg_G."""
    print("Original-vertex degrees in C(G) (all should equal |V| - 1):")
    for n in (4, 5, 6, 7):
        g = cycle_graph(n)
        degs = [central_degree(g, ("v", u)) for u in g[0]]
        print(f"  C_{n}: |V|={n}, target={n-1}, degrees={degs}, "
              f"uniform={all(d == n - 1 for d in degs)}")


if __name__ == "__main__":
